select c.id, c.name, c.address, c.location, c.check_in_method, c.check_in_distance, c.check_in_type_id, c.contact_phone, c.status, c.sort, c.introduction, c.images, c.remark, c.create_time, c.update_time, ct.name as check_in_type_name, ct.images as check_in_type_images from check_in_place c left join check_in_type ct on c.check_in_type_id = ct.id
and c.name like concat('%', #{param.keyword}, '%')
and c.check_in_type_id = #{param.searchId}
and c.check_in_method = #{param.searchType}
and c.status = #{param.searchIntStatus}
and c.create_time >= #{param.startTime}
and #{param.endTime} >= c.create_time
and c.delete_time is null
order by c.sort desc,c.id desc

